from sklearn.metrics import median_absolute_error
import numpy as np


def weekly_kpi(actual, forecast, demand_weight):
    \"\"\"Demand-weighted median absolute forecast error for one week (lower is better).\"\"\"
    errors = np.abs(np.asarray(actual) - np.asarray(forecast))
    weights = np.asarray(demand_weight)

    sorted_indices = np.argsort(errors)
    sorted_errors = errors[sorted_indices]
    sorted_weights = weights[sorted_indices]

    cumulative_weights = np.cumsum(sorted_weights)
    cutoff = np.sum(weights) / 2.0

    median_idx = np.searchsorted(cumulative_weights, cutoff)

    if median_idx < len(sorted_errors):
        return float(sorted_errors[median_idx])
    else:
        return float(sorted_errors[-1])

